'use client';

import { useMemo, useEffect, useState } from 'react';
import { TokenSource } from 'livekit-client';
import {
  RoomAudioRenderer,
  SessionProvider,
  StartAudio,
  useSession,
} from '@livekit/components-react';
import { useAuth } from '@/contexts/AuthContext';
import { Toaster } from '@/components/livekit/toaster';
import type { AppConfig } from '@/app-config';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Mic, MicOff, PhoneOff, MessageSquare, ArrowLeft } from 'lucide-react';
import { useRouter } from 'next/navigation';

/**
 * Multi-tenant Voice Agent Test Page
 * Simplified version that fits within dashboard layout
 */

interface VoiceAgentAppProps {
  tenantId: string;
}

function VoiceAgentApp({ tenantId }: VoiceAgentAppProps) {
  const router = useRouter();
  const [isConnected, setIsConnected] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [showChat, setShowChat] = useState(true);
  const [messages, setMessages] = useState<{role: string, text: string}[]>([]);

  // Create token source for this tenant
  const tokenSource = useMemo(() => {
    return TokenSource.custom(async () => {
      const res = await fetch('/api/connection-details', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: tenantId }),
      });
      
      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(`Failed to get connection details: ${errorText}`);
      }
      
      return await res.json();
    });
  }, [tenantId]);

  // Create session from token source
  const session = useSession(tokenSource);

  // Track connection state
  useEffect(() => {
    setIsConnected(session.isConnected);
  }, [session.isConnected]);

  // Handle connect/disconnect
  const handleToggleConnection = async () => {
    if (session.isConnected) {
      session.end();
      setIsConnected(false);
      setMessages([]);
    } else {
      try {
        await session.start();
        setIsConnected(true);
        setMessages([{ role: 'assistant', text: 'Hello! I\'m your AI receptionist. How can I help you today?' }]);
      } catch (error) {
        console.error('Failed to connect:', error);
      }
    }
  };

  // Handle mute toggle
  const handleToggleMute = () => {
    if (session.localParticipant?.isMicrophoneEnabled) {
      session.localParticipant.setMicrophoneEnabled(!isMuted);
      setIsMuted(!isMuted);
    }
  };

  return (
    <SessionProvider session={session}>
      <div className="p-6 h-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="icon" onClick={() => router.push('/dashboard/voice-agent/control-center')}>
              <ArrowLeft className="w-4 h-4" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold">Test Voice Agent</h1>
              <p className="text-muted-foreground">Talk to your AI receptionist</p>
            </div>
          </div>
          <div className={`px-3 py-1 rounded-full text-sm ${isConnected ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>
            {isConnected ? '🟢 Connected' : '⚪ Disconnected'}
          </div>
        </div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Controls Card */}
          <Card>
            <CardContent className="p-6 flex flex-col items-center justify-center min-h-[300px]">
              {/* Microphone Visual */}
              <div className={`w-32 h-32 rounded-full flex items-center justify-center mb-6 transition-all ${
                isConnected 
                  ? isMuted 
                    ? 'bg-red-100 border-4 border-red-500' 
                    : 'bg-green-100 border-4 border-green-500 animate-pulse'
                  : 'bg-gray-100 border-4 border-gray-300'
              }`}>
                {isMuted ? (
                  <MicOff className="w-12 h-12 text-red-500" />
                ) : (
                  <Mic className={`w-12 h-12 ${isConnected ? 'text-green-500' : 'text-gray-400'}`} />
                )}
              </div>

              {/* Status Text */}
              <p className="text-lg font-medium mb-6">
                {!isConnected 
                  ? 'Click to start talking'
                  : isMuted 
                    ? 'Microphone muted'
                    : 'Listening...'}
              </p>

              {/* Control Buttons */}
              <div className="flex gap-4">
                <Button
                  size="lg"
                  variant={isConnected ? "destructive" : "default"}
                  onClick={handleToggleConnection}
                  className="min-w-[150px]"
                >
                  {isConnected ? (
                    <>
                      <PhoneOff className="w-4 h-4 mr-2" />
                      End Call
                    </>
                  ) : (
                    <>
                      <Mic className="w-4 h-4 mr-2" />
                      Start Call
                    </>
                  )}
                </Button>

                {isConnected && (
                  <Button
                    size="lg"
                    variant="outline"
                    onClick={handleToggleMute}
                  >
                    {isMuted ? <MicOff className="w-4 h-4 mr-2" /> : <Mic className="w-4 h-4 mr-2" />}
                    {isMuted ? 'Unmute' : 'Mute'}
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Chat Transcript Card */}
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center gap-2 mb-4">
                <MessageSquare className="w-5 h-5" />
                <h3 className="font-semibold">Conversation</h3>
              </div>
              
              <div className="h-[250px] overflow-y-auto space-y-3 rounded-lg bg-muted/30 p-4">
                {messages.length === 0 ? (
                  <p className="text-center text-muted-foreground py-8">
                    Start a call to begin the conversation
                  </p>
                ) : (
                  messages.map((msg, i) => (
                    <div
                      key={i}
                      className={`p-3 rounded-lg ${
                        msg.role === 'user' 
                          ? 'bg-primary text-primary-foreground ml-8'
                          : 'bg-white border mr-8'
                      }`}
                    >
                      <p className="text-sm">{msg.text}</p>
                    </div>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Tips */}
        <Card className="mt-6">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <span className="text-2xl">💡</span>
              <div>
                <p className="font-medium">Tips for testing:</p>
                <ul className="text-sm text-muted-foreground mt-1 space-y-1">
                  <li>• Make sure your microphone is enabled in browser settings</li>
                  <li>• Speak clearly and wait for the AI to respond</li>
                  <li>• Try: "Hello", "I'd like to book an appointment", "What services do you offer?"</li>
                </ul>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Critical: Audio components */}
      <StartAudio label="Start Audio" />
      <RoomAudioRenderer />
      <Toaster />
    </SessionProvider>
  );
}

export default function VoiceAgentTestPage() {
  const { user, isLoading } = useAuth();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted || isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary" />
      </div>
    );
  }

  if (!user?.tenant_id) {
    return (
      <div className="flex flex-col items-center justify-center h-64">
        <h2 className="text-2xl font-bold mb-4">No Tenant Found</h2>
        <p className="text-muted-foreground">Please log in to test the voice agent.</p>
      </div>
    );
  }

  return <VoiceAgentApp tenantId={user.tenant_id} />;
}
